import sys

def generate_prices_matrix(N):
    # Initialize the matrix with zeros
    matrix = [[0] * N for _ in range(N)]

    # Fill the matrix with distinct prices
    price = 1
    for i in range(N):
        for j in range(i + 1, N):
            matrix[i][j] = price
            matrix[j][i] = price
            price += 1

    return matrix

def print_matrix(matrix):
    for row in matrix:
        print(" ".join(map(str, row)))

def main():
    import sys
    N = int(sys.stdin.read().strip())
    matrix = generate_prices_matrix(N)
    print_matrix(matrix)

if __name__ == "__main__":
    main()
